        example: "# 进程管理实例\n\n# 查看进程\nps aux | grep nginx       # 查找 nginx 进程\nps -ef --forest           # 树形显示进程\ntop -c                    # 实时监控（按 P CPU排序，M 内存排序）\n\n# 终止进程\nkill 1234                 # 发送 SIGTERM\nkill -9 1234              # 强制杀死 SIGKILL\npkill -f \"python app.py\"  # 按命令名杀\nkillall nginx             # 按进程名杀\n\n# 后台运行\nnohup python app.py &     # 后台运行不挂断\njobs -l                   # 查看后台任务"
