        content: "Node.js基于V8事件驱动I/O，单线程异步非阻塞，适合IO密集场景。事件循环6阶段：timers、pending callbacks、poll(核心IO轮询)、check(setImmediate)等。Express最流行Web框架，中间件(req,res,next)按顺序执行，错误中间件4参数(err,req,res,next)。Koa更轻量，洋葱模型+async/await，内置异常捕获。require() CommonJS同步，import ESM静态导入，可互操作。",
        example: "// Express 中间件实例\nconst express = require('express')\nconst app = express()\n\napp.use(express.json())\napp.use(express.static('public'))\n\n// 日志中间件\napp.use((req, res, next) => {\n  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`)\n  next()\n})\n\napp.get('/api/users', (req, res) => {\n  res.json({ users: [] })\n})\n\napp.post('/api/users', (req, res) => {\n  const { name } = req.body\n  if (!name) return res.status(400).json({ error: 'name required' })\n  res.status(201).json({ id: 1, name })\n})\n\n// 错误处理中间件\napp.use((err, req, res, next) => {\n  console.error(err.stack)\n  res.status(500).json({ error: '服务器内部错误' })\n})\n\napp.listen(3000, () => console.log('Server on :3000'))"
