        id: "be-postgresql-vs-mysql",
        title: "PostgreSQL对比MySQL",
        level: "基础",
        content: "PG与MySQL都是主流关系型数据库，各有侧重。PG功能最丰富开源库，支持JSONB二进制可索引、数组、GIS地理、全文搜索、CTE递归、窗口函数等高级特性。MySQL互联网领域更广，InnoDB引擎成熟稳定，MVCC+读写优化经大量生产验证。选型建议：PG适合复杂查询、数据分析、需丰富数据类型；MySQL适合OLTP高并发、生态工具链完善场景。PG MVCC基于快照旧版本存表内(VACUUM清理)；MySQL InnoDB MVCC基于undo log回滚段。两者都支持主从复制，PG内置流复制。",
        example: "-- PostgreSQL 特色查询实例\n\n-- JSONB 查询\nSELECT * FROM products\nWHERE attributes @> '{\"color\": \"red\"}';\n\n-- 递归 CTE 查询组织架构\nWITH RECURSIVE org_tree AS (\n  SELECT id, name, parent_id, 0 AS depth\n  FROM departments WHERE parent_id IS NULL\n  UNION ALL\n  SELECT d.id, d.name, d.parent_id, t.depth + 1\n  FROM departments d\n  JOIN org_tree t ON d.parent_id = t.id\n)\nSELECT * FROM org_tree ORDER BY depth;\n\n-- 窗口函数\nSELECT name, salary,\n  RANK() OVER (PARTITION BY dept ORDER BY salary DESC) AS rank\nFROM employees;"
