        id: "be-websocket",
        title: "WebSocket实时通信",
        level: "进阶",
        content: "WebSocket HTML5全双工协议，基于TCP，经HTTP Upgrade握手建连，默认端口80/443，解决HTTP单向请求-响应需低效轮询问题。握手用HTTP 101 Switching Protocols切换。与轮询Polling/SSE相比，WebSocket持久连接服务器主动推送，延迟低开销小。应用场景：即时聊天、在线协作文档、实时通知、在线游戏、股票行情。生产注意：心跳Ping/Pong检测断连；Nginx反代配proxy_read_timeout防长连接断开；wss=TLS加密防中间人；集群配合Redis Pub/Sub或Kafka广播消息，确保多节点可达。",
        example: "// WebSocket 服务端实例 (Node.js)\nconst { WebSocketServer } = require('ws')\nconst wss = new WebSocketServer({ port: 8080 })\nconst clients = new Set()\n\nwss.on('connection', (ws, req) => {\n  const clientId = Date.now()\n  ws.clientId = clientId\n  clients.add(ws)\n\n  // 广播消息\n  ws.on('message', (data) => {\n    const msg = JSON.parse(data)\n    const broadcast = JSON.stringify({\n      from: clientId,\n      text: msg.text,\n      time: new Date().toISOString()\n    })\n    clients.forEach(client => {\n      if (client.readyState === 1) client.send(broadcast)\n    })\n  })\n\n  ws.on('pong', () => { ws.isAlive = true })\n\n  ws.on('close', () => {\n    clients.delete(ws)\n    console.log(`客户端 ${clientId} 断开`)\n  })\n})\n\n// 心跳检测\nsetInterval(() => {\n  clients.forEach(ws => {\n    if (!ws.isAlive) return ws.terminate()\n    ws.isAlive = false\n    ws.ping()\n  })\n}, 30000)"
