        example: "#!/bin/bash\n# 循环结构演示 loops.sh\n\n# for 遍历列表\nfor fruit in apple banana cherry; do\n    echo \"水果: $fruit\"\ndone\n\n# for C 风格\nfor ((i=3; i>=1; i--)); do\n    echo \"$i...\"\n    sleep 1\ndone\necho \"发射!\"\n\n# while 读取文件\ncount=0\nwhile IFS=: read -r user pw uid rest; do\n    echo \"用户: $user (UID: $uid)\"\n    ((count++))\n    [[ $count -ge 3 ]] && break\ndone < /etc/passwd\n\n# until 等待服务\nattempts=0\nuntil ping -c1 -W1 8.8.8.8 &>/dev/null; do\n    ((attempts++))\n    echo \"尝试 $attempts...\"\n    [[ $attempts -ge 3 ]] && { echo \"连接失败\"; exit 1; }\n    sleep 2\ndone\necho \"网络连通!\""
