        example: "#!/bin/bash\n# grep 搜索实例\n\n# 基本搜索\ngrep \"error\" /var/log/messages\ngrep -i \"ERROR\" /var/log/messages     # 忽略大小写\ngrep -n \"error\" app.log               # 显示行号\ngrep -c \"error\" app.log               # 统计匹配行数\ngrep -v \"debug\" app.log               # 排除debug行\n\n# 递归搜索\ngrep -rn \"TODO\" ./src/                # 递归搜索代码\ngrep -rl \"password\" /etc/             # 只显示文件名\n\n# 扩展正则\ngrep -E \"error|warning|critical\" app.log\ngrep -E \"^import \" *.py               # Python import行\n\n# 上下文\ngrep -A 2 \"Exception\" app.log         # 匹配行+后2行\ngrep -C 3 \"Exception\" app.log         # 前后各3行\n\n# 管道组合\nps aux | grep nginx | grep -v grep    # 查找nginx进程\ndmesg | grep -i \"usb\" | head -10"
