        example: "#!/bin/bash\n# 性能优化对比实例\n\n# === 1. 内置 vs 外部命令 ===\nstr=\"hello world shell script\"\nlen=${#str}                       # 快：纯内置\n# len=$(echo \"$str\" | wc -c)     # 慢：启动子进程\n\n# === 2. 并行执行 ===\necho \"并行下载...\"\ntime (\n    curl -s http://httpbin.org/delay/2 -o /dev/null &\n    curl -s http://httpbin.org/delay/2 -o /dev/null &\n    curl -s http://httpbin.org/delay/2 -o /dev/null &\n    wait\n)\n# 约 2 秒（并行） vs 6 秒（串行）\n\n# === 3. xargs 并行 ===\necho \"1 2 3 4\" | tr ' ' '\\n' | xargs -P 4 -I{} bash -c '\n    echo \"处理 {} ...\"\n    sleep 2\n    echo \"{} 完成\"\n'\n\n# === 4. mapfile 读取文件 ===\nmapfile -t lines < /etc/passwd\necho \"读取 ${#lines[@]} 行\""
