        title: "Shell 脚本工程化",
        level: "高级",
        content: "工程化最佳实践：\n\n1. 严格模式：set -euo pipefail\n2. 日志函数：封装 log_info/log_warn/log_error\n3. 配置分离：source 外部配置文件\n4. 函数库：公共函数抽成独立文件\n5. 参数校验：检查必需参数\n6. 信号处理：trap 捕获信号做清理\n7. 退出码规范：0成功，非0不同错误类型\n8. usage 帮助：-h 显示用法\n9. 锁机制：防止脚本重复运行 (flock)\n10. ShellCheck：CI 中集成静态检查",
        example: "#!/bin/bash\n# 工程化脚本模板 template.sh\nset -euo pipefail\n\nSCRIPT_DIR=\"$(cd \"$(dirname \"$0\")\" && pwd)\"\nLOG_DIR=\"$SCRIPT_DIR/logs\"\nPID_FILE=\"/tmp/app_deploy.pid\"\n\n# 日志函数\nlog_info()  { echo \"[$(date '+%Y-%m-%d %H:%M:%S')] [INFO]  $*\"; }\nlog_error() { echo \"[$(date '+%Y-%m-%d %H:%M:%S')] [ERROR] $*\" >&2; }\n\n# 信号处理\ncleanup() { log_info \"清理资源...\"; rm -f \"$PID_FILE\"; exit 0; }\ntrap cleanup EXIT INT TERM\n\n# 防重复运行\nexec 9>\"$PID_FILE\"\nif ! flock -n 9; then\n    log_error \"脚本已在运行中\"\n    exit 1\nfi\necho $$ > \"$PID_FILE\"\n\n# 参数校验\nusage() {\n    echo \"用法: $0 -e ENV [-v] [-d]\"\n    echo \"  -e ENV  环境 (dev/staging/prod)\"\n    echo \"  -v      详细输出\"\n    echo \"  -d      干运行\"\n    exit 0\n}\n\nENV=\"\"\nDRY_RUN=false\nwhile getopts \":e:vdh\" opt; do\n    case $opt in\n        e) ENV=\"$OPTARG\" ;;\n        v) set -x ;;\n        d) DRY_RUN=true ;;\n        h) usage ;;\n        *) log_error \"未知选项\"; usage ;;\n    esac\ndone\n[[ -z \"$ENV\" ]] && { log_error \"请指定环境\"; usage; }\n\n# 主逻辑\nlog_info \"开始部署到 $ENV\"\nif [[ \"$DRY_RUN\" == true ]]; then\n    log_info \"[干运行] docker-compose up -d\"\nelse\n    git pull origin main\n    docker-compose build\n    docker-compose up -d\n    sleep 5\n    curl -sf http://localhost:8080/health | grep -q \"ok\" \\\n        && log_info \"部署成功\" \\\n        || { log_error \"健康检查失败\"; exit 1; }\nfi"
